/**
 * The types for the bundled agent API.
 *
 * `agentApi.js` is generated by `vite.agent-api.config.ts` and is not in the
 * repository; this file is, so the Vercel entry point next to it type-checks
 * before anything has been built. It re-exports the real declarations rather
 * than restating them, so the two cannot drift: a change to `serveAgentApi`'s
 * signature is a change here, without anybody editing this file.
 */

export { resetAgentApi, serveAgentApi } from '../agent/index'
